import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Manual } from '../types';
import { getManualDetail, deleteManual } from '../utils/manualApi';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import MarkdownViewer from '../components/MarkdownViewer';
import ManualDeleteConfirmModal from '../components/ManualDeleteConfirmModal';
import ManualVersionHistoryModal from '../components/ManualVersionHistoryModal';

const ManualDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { showToast } = useToast();

  const [manual, setManual] = useState<Manual | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [versionHistoryModalOpen, setVersionHistoryModalOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // 관리자 여부 (임시로 true로 설정, 실제로는 인증 정보에서 가져와야 함)
  const isAdmin = true;

  // 메뉴얼 상세 조회
  useEffect(() => {
    if (!id) {
      setError('메뉴얼 ID가 없습니다.');
      setLoading(false);
      return;
    }

    const fetchManual = async () => {
      try {
        setLoading(true);
        setError(null);
        const response = await getManualDetail(id);
        if (response.success) {
          setManual(response.data);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : '메뉴얼을 불러오는데 실패했습니다.');
      } finally {
        setLoading(false);
      }
    };

    fetchManual();
  }, [id]);

  // 삭제 모달 열기
  const handleOpenDeleteModal = () => {
    setDeleteModalOpen(true);
  };

  // 삭제 모달 닫기
  const handleCloseDeleteModal = () => {
    setDeleteModalOpen(false);
  };

  // 버전 히스토리 모달 열기
  const handleOpenVersionHistoryModal = () => {
    setVersionHistoryModalOpen(true);
  };

  // 버전 히스토리 모달 닫기
  const handleCloseVersionHistoryModal = () => {
    setVersionHistoryModalOpen(false);
  };

  // 메뉴얼 삭제
  const handleDeleteManual = async () => {
    if (!id || !manual) return;

    try {
      setIsDeleting(true);
      const response = await deleteManual(id);
      if (response.success) {
        showToast('메뉴얼이 성공적으로 삭제되었습니다.', 'success');
        navigate('/manuals');
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '메뉴얼 삭제에 실패했습니다.',
        'error'
      );
    } finally {
      setIsDeleting(false);
      setDeleteModalOpen(false);
    }
  };

  // 날짜 포맷팅
  const formatDate = (dateString: string): string => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('ko-KR', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return dateString;
    }
  };

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto">
        <LoadingSpinner />
      </div>
    );
  }

  if (error || !manual) {
    return (
      <div className="max-w-7xl mx-auto">
        <ErrorMessage
          message={error || '메뉴얼을 찾을 수 없습니다.'}
          onRetry={() => navigate('/manuals')}
        />
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto">
      {/* 헤더 */}
      <div className="mb-6 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate('/manuals')}
            className="text-gray-600 hover:text-gray-900 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <div className="flex items-center gap-3">
            <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-sm">
              {manual.categoryName}
            </span>
            <h1 className="text-2xl font-bold text-gray-900">
              {manual.title} <span className="text-lg text-gray-500">(v{manual.version})</span>
            </h1>
          </div>
        </div>
        {isAdmin && (
          <div className="flex gap-2">
            <button
              onClick={handleOpenVersionHistoryModal}
              className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
            >
              버전 히스토리
            </button>
            <button
              onClick={() => navigate(`/manuals/${id}/edit`)}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              수정
            </button>
            <button
              onClick={handleOpenDeleteModal}
              className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
            >
              삭제
            </button>
          </div>
        )}
      </div>

      {/* 메타 정보 */}
      <div className="bg-white rounded-lg shadow-sm p-4 mb-6">
        <div className="flex items-center gap-4 text-sm text-gray-500">
          <span>버전: {manual.version}</span>
          <span>작성일: {formatDate(manual.createdDate)}</span>
          {manual.updatedDate !== manual.createdDate && (
            <span>수정일: {formatDate(manual.updatedDate)}</span>
          )}
        </div>
      </div>

      {/* 본문 */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <MarkdownViewer content={manual.content} />
      </div>

      {/* 삭제 확인 모달 */}
      <ManualDeleteConfirmModal
        isOpen={deleteModalOpen}
        title={manual.title}
        onConfirm={handleDeleteManual}
        onCancel={handleCloseDeleteModal}
        isProcessing={isDeleting}
      />

      {/* 버전 히스토리 모달 */}
      {isAdmin && manual && (
        <ManualVersionHistoryModal
          isOpen={versionHistoryModalOpen}
          manualId={manual.id}
          onClose={handleCloseVersionHistoryModal}
        />
      )}
    </div>
  );
};

export default ManualDetailPage;
