import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { HostListItem, HostListFilterParams } from '../types';
import { getHostList, getHostDetail, resetHostPassword } from '../utils/hostApi';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import HostCard from '../components/HostCard';
import HostListFilters from '../components/HostListFilters';
import HostDetailModal from '../components/HostDetailModal';
import PasswordResetConfirmModal from '../components/PasswordResetConfirmModal';
import PasswordDisplayModal from '../components/PasswordDisplayModal';

const HostManagementPage: React.FC = () => {
  const [hostList, setHostList] = useState<HostListItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState<HostListFilterParams>({
    sortField: 'createdDate',
    sortDirection: 'DESC',
  });

  // 모달 상태
  const [selectedHost, setSelectedHost] = useState<HostListItem | null>(null);
  const [hostDetailModalOpen, setHostDetailModalOpen] = useState(false);
  const [passwordResetConfirmModalOpen, setPasswordResetConfirmModalOpen] = useState(false);
  const [passwordDisplayModalOpen, setPasswordDisplayModalOpen] = useState(false);
  const [resetPassword, setResetPassword] = useState<string | null>(null);
  const [isResettingPassword, setIsResettingPassword] = useState(false);

  const { showToast } = useToast();

  // Host 목록 조회
  const fetchHostList = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await getHostList();
      if (response.success) {
        setHostList(response.data);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Host 목록을 불러오는데 실패했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  // 초기 로딩
  useEffect(() => {
    fetchHostList();
  }, [fetchHostList]);

  // 필터링 및 정렬된 Host 목록
  const filteredAndSortedHosts = useMemo(() => {
    let filtered = [...hostList];

    // 검색 필터
    if (filters.searchTerm) {
      const searchTerm = filters.searchTerm.toLowerCase();
      filtered = filtered.filter(
        (item) =>
          item.host.hostName.toLowerCase().includes(searchTerm) ||
          item.host.contact.toLowerCase().includes(searchTerm) ||
          item.host.id.toLowerCase().includes(searchTerm)
      );
    }

    // 통장사본 필터
    if (filters.hasBankbook !== undefined) {
      filtered = filtered.filter((item) => {
        const hasBankbook = item.host.bankbookUrl !== null && item.host.bankbookUrl !== undefined;
        return filters.hasBankbook === hasBankbook;
      });
    }

    // Stay 연결 필터
    if (filters.hasStays !== undefined) {
      filtered = filtered.filter((item) => {
        const hasStays = item.stays.length > 0;
        return filters.hasStays === hasStays;
      });
    }

    // 정렬
    filtered.sort((a, b) => {
      const sortField = filters.sortField || 'createdDate';
      const sortDirection = filters.sortDirection || 'DESC';

      let aValue: any;
      let bValue: any;

      if (sortField === 'hostName') {
        aValue = a.host.hostName;
        bValue = b.host.hostName;
      } else if (sortField === 'createdDate') {
        aValue = new Date(a.host.createdDate).getTime();
        bValue = new Date(b.host.createdDate).getTime();
      } else if (sortField === 'updatedDate') {
        aValue = new Date(a.host.updatedDate).getTime();
        bValue = new Date(b.host.updatedDate).getTime();
      }

      if (aValue < bValue) return sortDirection === 'ASC' ? -1 : 1;
      if (aValue > bValue) return sortDirection === 'ASC' ? 1 : -1;
      return 0;
    });

    return filtered;
  }, [hostList, filters]);

  // Host 카드 클릭 핸들러
  const handleHostCardClick = async (hostItem: HostListItem) => {
    try {
      // Host 상세 정보 조회
      const response = await getHostDetail(hostItem.host.id);
      if (response.success) {
        setSelectedHost({
          host: response.data.host,
          stays: response.data.stays,
        });
        setHostDetailModalOpen(true);
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : 'Host 정보를 불러오는데 실패했습니다.',
        'error'
      );
    }
  };

  // Host 상세 정보 업데이트
  const handleHostUpdate = async () => {
    if (!selectedHost) return;

    try {
      const response = await getHostDetail(selectedHost.host.id);
      if (response.success) {
        setSelectedHost({
          host: response.data.host,
          stays: response.data.stays,
        });
        // 목록도 업데이트
        setHostList((prev) =>
          prev.map((item) =>
            item.host.id === selectedHost.host.id
              ? {
                  host: response.data.host,
                  stays: response.data.stays,
                }
              : item
          )
        );
      }
    } catch (err) {
      console.error('Host 정보 업데이트 실패:', err);
    }
  };

  // 비밀번호 초기화 핸들러
  const handlePasswordReset = () => {
    if (selectedHost) {
      setPasswordResetConfirmModalOpen(true);
    }
  };

  // 비밀번호 초기화 확인
  const handlePasswordResetConfirm = async () => {
    if (!selectedHost) return;

    setIsResettingPassword(true);
    try {
      const response = await resetHostPassword(selectedHost.host.id);
      if (response.success) {
        setResetPassword(response.data.newPassword);
        setPasswordResetConfirmModalOpen(false);
        setPasswordDisplayModalOpen(true);
        // Host 정보 업데이트
        setSelectedHost({
          host: response.data.host,
          stays: selectedHost.stays,
        });
        // 목록도 업데이트
        setHostList((prev) =>
          prev.map((item) =>
            item.host.id === selectedHost.host.id
              ? {
                  host: response.data.host,
                  stays: item.stays,
                }
              : item
          )
        );
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '비밀번호 초기화에 실패했습니다.',
        'error'
      );
    } finally {
      setIsResettingPassword(false);
    }
  };

  // 필터 초기화
  const handleFilterReset = () => {
    setFilters({
      sortField: 'createdDate',
      sortDirection: 'DESC',
    });
  };

  return (
    <div>
      <div className="max-w-7xl mx-auto">
        <h1 className="text-2xl font-bold text-gray-900 mb-6">Host 관리</h1>

        {loading && <LoadingSpinner />}

        {error && (
          <ErrorMessage message={error} onRetry={fetchHostList} />
        )}

        {!loading && !error && (
          <>
            {/* 필터 영역 */}
            <HostListFilters
              filters={filters}
              onFilterChange={setFilters}
              onReset={handleFilterReset}
            />

            {/* Host 목록 */}
            {filteredAndSortedHosts.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredAndSortedHosts.map((hostItem) => (
                  <HostCard
                    key={hostItem.host.id}
                    hostItem={hostItem}
                    onClick={() => handleHostCardClick(hostItem)}
                  />
                ))}
              </div>
            ) : (
              <div className="bg-white rounded-lg shadow-sm p-8 text-center">
                <p className="text-gray-600">
                  {filters.searchTerm || filters.hasBankbook !== undefined || filters.hasStays !== undefined
                    ? '검색 결과가 없습니다.'
                    : '등록된 Host가 없습니다.'}
                </p>
              </div>
            )}
          </>
        )}
      </div>

      {/* Host 상세 모달 */}
      {selectedHost && (
        <HostDetailModal
          isOpen={hostDetailModalOpen}
          host={selectedHost.host}
          stays={selectedHost.stays}
          onClose={() => {
            setHostDetailModalOpen(false);
            setSelectedHost(null);
          }}
          onUpdate={handleHostUpdate}
          onPasswordReset={handlePasswordReset}
          isPasswordModalOpen={passwordResetConfirmModalOpen || passwordDisplayModalOpen}
        />
      )}

      {/* 비밀번호 초기화 확인 모달 */}
      {selectedHost && (
        <PasswordResetConfirmModal
          isOpen={passwordResetConfirmModalOpen}
          hostName={selectedHost.host.hostName}
          onConfirm={handlePasswordResetConfirm}
          onCancel={() => setPasswordResetConfirmModalOpen(false)}
          isProcessing={isResettingPassword}
        />
      )}

      {/* 비밀번호 표시 모달 */}
      {selectedHost && resetPassword && (
        <PasswordDisplayModal
          isOpen={passwordDisplayModalOpen}
          password={resetPassword}
          hostName={selectedHost.host.hostName}
          onClose={() => {
            setPasswordDisplayModalOpen(false);
            setResetPassword(null);
          }}
        />
      )}
    </div>
  );
};

export default HostManagementPage;

