// 구글 지오코딩 API 함수
export interface GeocodeResult {
  lat: number;
  lng: number;
}

// 구글 지도 로드 대기 함수
const waitForGoogleMaps = (): Promise<void> => {
  return new Promise((resolve) => {
    if ((window as any).google && (window as any).google.maps) {
      resolve();
    } else {
      const checkGoogle = () => {
        if ((window as any).google && (window as any).google.maps) {
          resolve();
        } else {
          setTimeout(checkGoogle, 100);
        }
      };
      checkGoogle();
    }
  });
};

export const getGoogleGeocode = async (address: string): Promise<GeocodeResult> => {
  await waitForGoogleMaps();
  const geocoder = new (window.google as any).maps.Geocoder();
  
  return new Promise((resolve, reject) => {
    geocoder.geocode({ address }, (results: any, status: any) => {
      if (status === 'OK' && results && results[0]) {
        const location = results[0].geometry.location;
        resolve({
          lat: location.lat(),
          lng: location.lng()
        });
      } else {
        reject(new Error('주소를 찾을 수 없습니다.'));
      }
    });
  });
};

// Stay 이름 생성 함수 (서울 제거)
export const generateStayName = (address: string): string => {
  return address.replace(/^서울특별시\s*/, '');
};

// Stay 생성 API 함수
export interface CreateStayRequest {
  address: string;
  detail_address: string;
  lat: number;
  lng: number;
  stay_name: string;
  stay_id: string;
  note: string;
  display_info: string;
  service_user_id?: string;
}

export const createStay = async (request: CreateStayRequest): Promise<void> => {
  const url = `${API_BASE_URL}/api/stays`;
  
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      mode: 'cors',
      body: JSON.stringify(request)
    });

    if (!response.ok) {
      if (response.status === 403) {
        throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
      } else if (response.status === 404) {
        throw new Error('요청한 리소스를 찾을 수 없습니다.');
      } else if (response.status >= 500) {
        throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
      } else {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
    }
  } catch (error) {
    if (error instanceof TypeError && error.message.includes('fetch')) {
      throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
    }
    throw error;
  }
};

// Stay 생성을 위한 헬퍼 함수
export const createStayFromInput = async (koreanAddress: string, note: string): Promise<void> => {
  // 1. 주소 번역
  const translationResult = await translateAddress({ address: koreanAddress });
  
  // 2. 지오코딩
  const geocodeResult = await getGoogleGeocode(translationResult.englishAddress);
  
  // 3. Stay 이름 생성
  const stayName = generateStayName(koreanAddress);
  
  // 4. Stay 생성
  const stayRequest: CreateStayRequest = {
    address: translationResult.englishAddress,
    detail_address: translationResult.englishDetailAddress,
    lat: geocodeResult.lat,
    lng: geocodeResult.lng,
    stay_name: stayName,
    stay_id: uuidv4(),
    note: note,
    display_info: translationResult.englishAddress
  };
  
  await createStay(stayRequest);
}; 