import React, { useState, useEffect } from 'react';
import { ManualCategory } from '../types';

interface ManualCategoryEditorModalProps {
  isOpen: boolean;
  category: ManualCategory | null; // null이면 생성 모드
  onConfirm: (name: string, sortOrder?: number) => void;
  onCancel: () => void;
  isProcessing?: boolean;
}

const ManualCategoryEditorModal: React.FC<ManualCategoryEditorModalProps> = ({
  isOpen,
  category,
  onConfirm,
  onCancel,
  isProcessing = false,
}) => {
  const [name, setName] = useState('');
  const [sortOrder, setSortOrder] = useState<number | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);

  // 카테고리 데이터 로드
  useEffect(() => {
    if (isOpen) {
      if (category) {
        setName(category.name);
        setSortOrder(category.sortOrder);
      } else {
        setName('');
        setSortOrder(undefined);
      }
      setError(null);
    }
  }, [isOpen, category]);

  // 확인 핸들러
  const handleConfirm = () => {
    if (!name.trim()) {
      setError('카테고리명을 입력해주세요.');
      return;
    }

    onConfirm(name.trim(), sortOrder);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-lg shadow-xl p-6 max-w-md w-full mx-4">
        <h2 className="text-xl font-bold text-gray-900 mb-4">
          {category ? '카테고리 수정' : '카테고리 생성'}
        </h2>
        
        <div className="space-y-4">
          {/* 카테고리명 */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              카테고리명 <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                setError(null);
              }}
              disabled={isProcessing}
              className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                error ? 'border-red-500' : 'border-gray-300'
              } disabled:bg-gray-100 disabled:cursor-not-allowed`}
              placeholder="카테고리명을 입력하세요"
            />
            {error && (
              <p className="mt-1 text-sm text-red-500">{error}</p>
            )}
          </div>

          {/* 순서 */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              순서 (선택)
            </label>
            <input
              type="number"
              value={sortOrder !== undefined ? sortOrder : ''}
              onChange={(e) => {
                const value = e.target.value;
                setSortOrder(value === '' ? undefined : parseInt(value, 10));
              }}
              disabled={isProcessing}
              min="1"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:bg-gray-100 disabled:cursor-not-allowed"
              placeholder="순서를 입력하세요 (미입력 시 자동 배치)"
            />
            <p className="mt-1 text-xs text-gray-500">
              순서를 지정하지 않으면 마지막 순서로 자동 배치됩니다.
            </p>
          </div>
        </div>

        {/* 버튼 */}
        <div className="flex justify-end gap-3 mt-6">
          <button
            onClick={onCancel}
            disabled={isProcessing}
            className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            취소
          </button>
          <button
            onClick={handleConfirm}
            disabled={isProcessing}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isProcessing ? '처리 중...' : category ? '수정' : '생성'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ManualCategoryEditorModal;
