import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Announcement,
  AnnouncementFilterParams,
  AnnouncementPagination,
} from '../types';
import { getAnnouncementList, deleteAnnouncement } from '../utils/announcementApi';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import AnnouncementFilters from '../components/AnnouncementFilters';
import AnnouncementDeleteConfirmModal from '../components/AnnouncementDeleteConfirmModal';
import { getPlainTextPreview } from '../utils/markdownUtils';

const AnnouncementPage: React.FC = () => {
  const navigate = useNavigate();
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [pagination, setPagination] = useState<AnnouncementPagination | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  
  const [filters, setFilters] = useState<AnnouncementFilterParams>({
    page: 0,
    size: 20,
  });

  // 삭제 확인 모달 상태
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [deletingAnnouncement, setDeletingAnnouncement] = useState<Announcement | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const { showToast } = useToast();

  // 공지사항 목록 조회
  const fetchAnnouncements = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      
      const response = await getAnnouncementList(filters);
      if (response.success) {
        setAnnouncements(response.data.announcements);
        setPagination(response.data.pagination);
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : '공지사항 목록을 불러오는데 실패했습니다.';
      setError(errorMessage);
      showToast(errorMessage, 'error');
    } finally {
      setLoading(false);
    }
  }, [filters, showToast]);

  // 초기 로딩
  useEffect(() => {
    fetchAnnouncements();
  }, [fetchAnnouncements]);

  // 필터 변경 핸들러
  const handleFilterChange = (newFilters: Partial<AnnouncementFilterParams>) => {
    setFilters(prev => ({
      ...prev,
      ...newFilters,
      page: newFilters.page !== undefined ? newFilters.page : 0, // 필터 변경 시 첫 페이지로
    }));
  };

  // 페이지 변경
  const handlePageChange = (page: number) => {
    setFilters(prev => ({ ...prev, page }));
  };

  // 필터 초기화
  const handleFilterReset = () => {
    setFilters({
      page: 0,
      size: 20,
    });
  };

  // 날짜 포맷팅
  const formatDate = (dateString: string): string => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('ko-KR', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return dateString;
    }
  };

  // 공지사항 클릭 핸들러 (상세 페이지로 이동)
  const handleAnnouncementClick = (announcement: Announcement) => {
    navigate(`/announcements/${announcement.id}`);
  };

  // 수정 버튼 클릭 핸들러
  const handleEditClick = (e: React.MouseEvent, announcement: Announcement) => {
    e.stopPropagation();
    navigate(`/announcements/${announcement.id}/edit`);
  };

  // 삭제 버튼 클릭 핸들러
  const handleDeleteClick = (e: React.MouseEvent, announcement: Announcement) => {
    e.stopPropagation();
    setDeletingAnnouncement(announcement);
    setDeleteModalOpen(true);
  };


  // 공지사항 삭제
  const handleDeleteAnnouncement = async () => {
    if (!deletingAnnouncement) return;

    try {
      setIsDeleting(true);
      const response = await deleteAnnouncement(deletingAnnouncement.id);
      if (response.success) {
        showToast('공지사항이 성공적으로 삭제되었습니다.', 'success');
        setDeleteModalOpen(false);
        setDeletingAnnouncement(null);
        await fetchAnnouncements(); // 목록 새로고침
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '공지사항 삭제에 실패했습니다.',
        'error'
      );
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900">공지사항</h1>
      </div>

      {loading && <LoadingSpinner />}

      {error && (
        <ErrorMessage message={error} onRetry={fetchAnnouncements} />
      )}

      {!loading && !error && (
        <>
          {/* 헤더 영역 (생성 버튼 포함) */}
          <div className="mb-4 flex justify-end">
            <button
              onClick={() => navigate('/announcements/new')}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              공지사항 작성
            </button>
          </div>

          {/* 필터 영역 */}
          <AnnouncementFilters
            filters={filters}
            onFilterChange={handleFilterChange}
            onReset={handleFilterReset}
          />

          {/* 공지사항 목록 */}
          {announcements.length > 0 ? (
            <div className="space-y-4">
              {announcements.map((announcement) => (
                <div
                  key={announcement.id}
                  className="bg-white rounded-lg shadow-sm p-6 hover:shadow-md transition-shadow"
                >
                  <div className="flex items-start justify-between">
                    <div
                      className="flex-1 cursor-pointer"
                      onClick={() => handleAnnouncementClick(announcement)}
                    >
                      <div className="flex items-center gap-2 mb-2">
                        {announcement.isPinned && (
                          <span className="inline-flex items-center px-2 py-1 rounded text-xs font-medium bg-yellow-100 text-yellow-800">
                            고정
                          </span>
                        )}
                        <h2 className="text-lg font-semibold text-gray-900">
                          {announcement.title}
                        </h2>
                      </div>
                      
                      <p className="text-gray-600 mb-3">
                        {getPlainTextPreview(announcement.content)}
                      </p>
                      
                      <div className="flex items-center gap-4 text-sm text-gray-500">
                        <span>조회수: {announcement.viewCount}</span>
                        <span>작성일: {formatDate(announcement.createdDate)}</span>
                        {announcement.updatedDate !== announcement.createdDate && (
                          <span>수정일: {formatDate(announcement.updatedDate)}</span>
                        )}
                      </div>
                    </div>
                    <div className="flex gap-2 ml-4">
                      <button
                        onClick={(e) => handleEditClick(e, announcement)}
                        className="px-3 py-1 text-sm bg-blue-100 text-blue-700 rounded hover:bg-blue-200 transition-colors"
                      >
                        수정
                      </button>
                      <button
                        onClick={(e) => handleDeleteClick(e, announcement)}
                        className="px-3 py-1 text-sm bg-red-100 text-red-700 rounded hover:bg-red-200 transition-colors"
                      >
                        삭제
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="bg-white rounded-lg shadow-sm p-8 text-center">
              <p className="text-gray-600">등록된 공지사항이 없습니다.</p>
            </div>
          )}

          {/* 페이지네이션 */}
          {pagination && pagination.totalPages > 0 && (
            <div className="mt-6 bg-white rounded-lg shadow-sm p-4">
              <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                {/* 결과 요약 */}
                <div className="text-sm text-gray-600">
                  총 {pagination.totalElements}건 중 {pagination.currentPage * pagination.size + 1} - {Math.min((pagination.currentPage + 1) * pagination.size, pagination.totalElements)}건 표시
                </div>
                
                {/* 페이지 버튼 */}
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => handlePageChange(pagination.currentPage - 1)}
                    disabled={!pagination.hasPrevious}
                    className={`px-3 py-1 rounded-lg text-sm ${
                      pagination.hasPrevious
                        ? 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                    }`}
                  >
                    ◀ 이전
                  </button>
                  
                  {/* 페이지 번호 */}
                  <div className="flex items-center gap-1">
                    {Array.from({ length: Math.min(5, pagination.totalPages) }, (_, i) => {
                      // 현재 페이지 주변 5개 표시
                      let pageNum: number;
                      if (pagination.totalPages <= 5) {
                        pageNum = i;
                      } else if (pagination.currentPage < 3) {
                        pageNum = i;
                      } else if (pagination.currentPage > pagination.totalPages - 3) {
                        pageNum = pagination.totalPages - 5 + i;
                      } else {
                        pageNum = pagination.currentPage - 2 + i;
                      }
                      
                      return (
                        <button
                          key={pageNum}
                          onClick={() => handlePageChange(pageNum)}
                          className={`w-8 h-8 rounded-lg text-sm ${
                            pagination.currentPage === pageNum
                              ? 'bg-blue-600 text-white'
                              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                          }`}
                        >
                          {pageNum + 1}
                        </button>
                      );
                    })}
                  </div>
                  
                  <button
                    onClick={() => handlePageChange(pagination.currentPage + 1)}
                    disabled={!pagination.hasNext}
                    className={`px-3 py-1 rounded-lg text-sm ${
                      pagination.hasNext
                        ? 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                    }`}
                  >
                    다음 ▶
                  </button>
                </div>
              </div>
            </div>
          )}
        </>
      )}

      {/* 삭제 확인 모달 */}
      <AnnouncementDeleteConfirmModal
        isOpen={deleteModalOpen}
        title={deletingAnnouncement?.title || ''}
        onConfirm={handleDeleteAnnouncement}
        onCancel={() => {
          setDeleteModalOpen(false);
          setDeletingAnnouncement(null);
        }}
        isProcessing={isDeleting}
      />
    </div>
  );
};

export default AnnouncementPage;
