import React, { useRef, useState } from 'react';
import { QRCodeSVG, QRCodeCanvas } from 'qrcode.react';
import { jsPDF } from 'jspdf';
import { HostStay } from '../types';
import { useToast } from '../hooks/useToast';

interface StayQRCodeModalProps {
  isOpen: boolean;
  stay: HostStay;
  onClose: () => void;
}

const StayQRCodeModal: React.FC<StayQRCodeModalProps> = ({
  isOpen,
  stay,
  onClose,
}) => {
  const canvasRef = useRef<HTMLDivElement>(null);
  const [isPosterDownloading, setIsPosterDownloading] = useState(false);
  const { showToast } = useToast();

  // QR 코드에 담을 값 (Stay 접속 URL)
  const qrValue = `https://koreaorder.com/stays/${stay.stayId}`;

  // QR 코드 다운로드
  const handleDownload = () => {
    const canvas = canvasRef.current?.querySelector('canvas');
    if (canvas) {
      const url = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.download = `QR_${stay.stayName}_${stay.stayId}.png`;
      link.href = url;
      link.click();
      showToast('QR 코드가 다운로드되었습니다.', 'success');
    }
  };

  // QR 코드 클립보드 복사
  const handleCopy = async () => {
    const canvas = canvasRef.current?.querySelector('canvas');
    if (canvas) {
      try {
        const blob = await new Promise<Blob | null>((resolve) => {
          canvas.toBlob(resolve, 'image/png');
        });
        if (blob) {
          await navigator.clipboard.write([
            new ClipboardItem({ 'image/png': blob }),
          ]);
          showToast('QR 코드가 클립보드에 복사되었습니다.', 'success');
        }
      } catch (error) {
        showToast('클립보드 복사에 실패했습니다.', 'error');
      }
    }
  };

  // 포스터 + QR 코드 합성 다운로드
  const handlePosterDownload = async () => {
    const qrCanvas = canvasRef.current?.querySelector('canvas');
    if (!qrCanvas) return;

    setIsPosterDownloading(true);
    try {
      // 포스터 이미지 로드
      const posterImg = new Image();
      posterImg.crossOrigin = 'anonymous';
      await new Promise<void>((resolve, reject) => {
        posterImg.onload = () => resolve();
        posterImg.onerror = () => reject(new Error('포스터 이미지를 불러올 수 없습니다.'));
        posterImg.src = `${process.env.PUBLIC_URL}/poster.jpg`;
      });

      // 오프스크린 캔버스 생성 (포스터 원본 크기)
      const offscreen = document.createElement('canvas');
      offscreen.width = posterImg.naturalWidth;
      offscreen.height = posterImg.naturalHeight;
      const ctx = offscreen.getContext('2d');
      if (!ctx) return;

      // 포스터 이미지 그리기
      ctx.drawImage(posterImg, 0, 0);

      // 포스터 내 흰색 QR 영역 좌표 (1748x2480 기준)
      const whiteArea = {
        x: 547,
        y: 1042,
        width: 654,
        height: 642,
      };

      // QR 코드를 흰색 영역 중앙에 배치 (여백 5px)
      const margin = 5;
      const qrSize = Math.min(whiteArea.width, whiteArea.height) - margin * 2;
      const qrX = whiteArea.x + (whiteArea.width - qrSize) / 2;
      const qrY = whiteArea.y + (whiteArea.height - qrSize) / 2;

      ctx.drawImage(qrCanvas, qrX, qrY, qrSize, qrSize);

      // 우측 하단에 Stay 주소 텍스트 표시 (노란색, 작은 크기)
      const stayAddress = stay.stayName;
      const fontSize = 32; // 1748x2480 기준 작은 크기
      const textPadding = 24;
      ctx.font = `${fontSize}px sans-serif`;
      ctx.fillStyle = '#FFD700';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'bottom';
      ctx.fillText(stayAddress, offscreen.width - textPadding, offscreen.height - textPadding);

      // 합성 이미지를 PDF로 다운로드
      const imgData = offscreen.toDataURL('image/jpeg', 0.95);
      const pdfWidth = offscreen.width;
      const pdfHeight = offscreen.height;
      const pdf = new jsPDF({
        orientation: pdfHeight > pdfWidth ? 'portrait' : 'landscape',
        unit: 'px',
        format: [pdfWidth, pdfHeight],
      });
      pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
      pdf.save(`Poster_QR_${stay.stayName}_${stay.stayId}.pdf`);
      showToast('포스터가 다운로드되었습니다.', 'success');
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '포스터 다운로드에 실패했습니다.',
        'error'
      );
    } finally {
      setIsPosterDownloading(false);
    }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-md animate-fade-in">
        {/* 헤더 */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200">
          <h3 className="text-lg font-medium text-gray-900">QR 코드</h3>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 transition-colors"
            aria-label="모달 닫기"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* 내용 */}
        <div className="p-6">
          {/* Stay 정보 */}
          <div className="mb-4 text-center">
            <h4 className="font-semibold text-gray-900">{stay.stayName}</h4>
            <p className="text-sm text-gray-500">Stay ID: {stay.stayId}</p>
          </div>

          {/* QR 코드 표시 (SVG - 화면 표시용) */}
          <div className="flex justify-center mb-4 p-4 bg-white rounded-lg border border-gray-200">
            <QRCodeSVG
              value={qrValue}
              size={200}
              level="M"
              marginSize={2}
              bgColor="#ffffff"
              fgColor="#000000"
            />
          </div>

          {/* QR 코드 (Canvas - 다운로드/복사용, 숨김) */}
          <div ref={canvasRef} className="hidden">
            <QRCodeCanvas
              value={qrValue}
              size={400}
              level="M"
              marginSize={2}
              bgColor="#ffffff"
              fgColor="#000000"
            />
          </div>

          {/* QR 값 표시 */}
          <div className="mb-6 p-3 bg-gray-50 rounded-lg">
            <p className="text-xs text-gray-500 mb-1">QR 코드 내용</p>
            <p className="text-sm text-gray-900 font-mono break-all">{qrValue}</p>
          </div>

          {/* 버튼들 */}
          <div className="flex gap-3">
            <button
              onClick={handleCopy}
              className="flex-1 px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors flex items-center justify-center gap-2"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
              복사
            </button>
            <button
              onClick={handleDownload}
              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
              다운로드
            </button>
          </div>

          {/* 포스터 다운로드 버튼 */}
          <button
            onClick={handlePosterDownload}
            disabled={isPosterDownloading}
            className="w-full mt-3 px-4 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
            {isPosterDownloading ? '포스터 생성 중...' : '포스터 다운로드'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default StayQRCodeModal;
